SELECT COALESCE(MAX(display_order), -1) + 1
FROM user_cards
WHERE user_id = #{userId}

SELECT user_card_id, codef_card_key_hash, is_active
FROM user_cards
WHERE codef_account_credential_id = #{linkId}
  AND user_id = #{userId}

SELECT user_card_id
FROM user_cards
WHERE user_id = #{userId}
  AND codef_card_key_hash = #{codefCardKeyHash}

